<?php
declare(strict_types=1);
namespace TNL\Mail;
require_once __DIR__.'/ReceptionWorker.php';
final class ReceptionDiagnostic {
 public static function send(\PDO $db,string $storage,string $request): array {
  if(!preg_match('/^[a-f0-9]{32}$/D',$request))throw new \InvalidArgumentException('Identificador inválido.');$key='reception_loopback_'.$request;$previous=\TNL\Admin\Settings::get($db,$key);if($previous!=='')return json_decode($previous,true)+['duplicate_prevented'=>true];$owner=Reception::owner($db);if($owner==='')throw new \RuntimeException('Activa primero la recepción.');$account=(new ExternalAccount($db,$storage))->load($owner);if(!$account||strtolower($account['email'])!=='claudetest@cache.lat')throw new \RuntimeException('La prueba solo puede enviarse a claudetest@cache.lat desde ese mismo buzón.');$staff=Reception::staff($db);if(!$staff)throw new \RuntimeException('Falta un usuario interno activo.');$user=$staff[0];foreach($staff as $u)if(strcasecmp($u['internal_address'],$account['email'])===0)$user=$u;$route=Reception::outbound($db,$owner,(int)$user['id'],[$account['email']],$storage);\TNL\Admin\Settings::set($db,$key,json_encode(['state'=>'attempting','token'=>$route['token'],'expected_user'=>(int)$user['id']]));
  try{$subject='TNL recepción · prueba '.substr($request,0,8);$body='<p>Prueba técnica de recepción compartida. Este mensaje se envía a la misma cuenta para comprobar SMTP, IMAP y asignación interna.</p>';$mid=ExternalMail::send($account,$account['email'],$subject,$body,null,$route,'html');Reception::link($db,$owner,$mid,$route['token']);$result=['state'=>'smtp_accepted','message_id'=>$mid,'expected_user'=>(int)$user['id'],'token'=>$route['token'],'subject'=>$subject,'recipient'=>$account['email']];}catch(\Throwable $e){$result=['state'=>'unconfirmed','token'=>$route['token'],'expected_user'=>(int)$user['id']];}\TNL\Admin\Settings::set($db,$key,json_encode($result));return $result;
 }
 public static function result(\PDO $db,string $request): array {if(!preg_match('/^[a-f0-9]{32}$/D',$request))throw new \InvalidArgumentException('Identificador inválido.');$r=json_decode(\TNL\Admin\Settings::get($db,'reception_loopback_'.$request,'{}'),true);if(empty($r['token']))return ['state'=>'unknown'];$q=$db->prepare('SELECT id,assigned_user,message_id FROM reception_messages WHERE token=? ORDER BY id DESC LIMIT 1');$q->execute([$r['token']]);$m=$q->fetch(\PDO::FETCH_ASSOC);return ['state'=>$r['state'],'imported'=>(bool)$m,'assigned_correctly'=>$m&&(int)$m['assigned_user']===(int)$r['expected_user'],'message_id'=>$r['message_id']??'','reception_id'=>$m?(int)$m['id']:null];}
}
